#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 60

static long long memo[MAX_N + 1][MAX_N + 1];
static char computed[MAX_N + 1][MAX_N + 1];

static long long binom(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;
    if (computed[n][k]) return memo[n][k];
    long long v = binom(n - 1, k - 1) + binom(n - 1, k);
    memo[n][k] = v;
    computed[n][k] = 1;
    return v;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    long n = strtol(argv[1], &end1, 10);
    long k = strtol(argv[2], &end2, 10);

    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0 || n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long result = binom((int)n, (int)k);
    printf("%lld\n", result);
    return 0;
}
